-- =====================================================================
-- KELİME EVRENİ — Gemini teyidi sonrası düzeltmeler
--
-- 1. Anlam metinleri (mühim, sol, düş): döngüsel tanım ve yazım düzeltmesi.
-- 2. Örnek ve hatırlatıcı metinleri: kaynak sinif-*.json (uret-icerik-migration gövdesi).
-- 3. Yalnızca TASLAK soruların yeniden üretimi. Yayında soru yoktur (kontrol edilir).
-- Üretici: uret-duzeltme-migration.mjs. Teyit: teyit-gemini.json.
-- =====================================================================

-- 1. Anlamlar
update public.kelime_anlamlari set anlam = 'Kendisine özen gösterilmesi gereken, dikkate değer, ehemmiyetli'
where kelime = 'mühim' and anlam = 'Önemli, değerli, ehemmiyetli'
  and not exists (select 1 from public.kelime_anlamlari x where x.kelime = 'mühim' and x.anlam = 'Kendisine özen gösterilmesi gereken, dikkate değer, ehemmiyetli');

update public.kelime_anlamlari set anlam = 'Müzikte yedi ana notadan biri'
where kelime = 'sol' and anlam = 'Müzikte yedi nottan biri'
  and not exists (select 1 from public.kelime_anlamlari x where x.kelime = 'sol' and x.anlam = 'Müzikte yedi ana notadan biri');

update public.kelime_anlamlari set anlam = 'Zihinde canlanan, gerçek olmayan imge'
where kelime = 'düş' and anlam = 'Uyurken zihinde beliren görüntü, rüya'
  and not exists (select 1 from public.kelime_anlamlari x where x.kelime = 'düş' and x.anlam = 'Zihinde canlanan, gerçek olmayan imge');

-- 2. Örnek ve hatırlatıcılar

alter table public.kelime_iliskileri
  add column if not exists ornek text check (ornek is null or length(btrim(ornek)) between 5 and 300),
  add column if not exists hatirlatici text check (hatirlatici is null or length(btrim(hatirlatici)) between 5 and 300),
  add column if not exists teknik text check (teknik is null or length(btrim(teknik)) between 2 and 40);

comment on column public.kelime_iliskileri.ornek is 'İlişkiyi gösteren örnek cümle (öğrenciye gösterim).';
comment on column public.kelime_iliskileri.hatirlatici is 'Çocuk için hafıza ipucu.';
comment on column public.kelime_iliskileri.teknik is 'Kullanılan hafıza tekniği etiketi (çağrışım, hikâye, görsel, hareket, ses, eşleştirme, karşıtlık).';

create temp table kelime_icerik_girdi (
  ka text not null, kan text not null, ha text not null, han text not null, tur text not null,
  ornek text not null, hatirlatici text not null, teknik text not null
) on commit drop;

